#define norm_pt(v) { register double r = sqrt( ( ( v )->x * ( v )->x ) + \
 ( ( v )->y * ( v )->y ) + \
 ( ( v )->z * ( v )->z ) ); \
 ( v )->x /= r; \
 ( v )->y /= r; \
 ( v )->z /= r; \
 }

subdivide_tri(p1,p2,p3,a)

 struct Point_struct *p1, *p2, *p3;
 int a;

 {

 struct Point_struct n1, n2, n3;
 struct Point_struct p12, p13, p23;
 double den, t;

 if (a>0) {

 p12.x = (p1->x+p2->x)/2.0;
 p12.y = (p1->y+p2->y)/2.0;
 p12.z = (p1->z+p2->z)/2.0;
 den = (p12.x*p12.x)+(p12.y*p12.y)+(p12.z*p12.z); 
 den = sqrt(den);
 if (den != 0.0) {

 t = radius / den;
 p12.x *= t; 
 p12.y *= t; 
 p12.z *= t;

 }
 p13.x = (p1->x+p3->x)/2.0;
 p13.y = (p1->y+p3->y)/2.0;
 p13.z = (p1->z+p3->z)/2.0;
 den = (p13.x*p13.x)+(p13.y*p13.y)+(p13.z*p13.z); 
 den = sqrt(den);
 if (den != 0.0) {

 t = radius / den;
 p13.x *= t; 
 p13.y *= t; 
 p13.z *= t;

 }
 p23.x = (p2->x+p3->x)/2.0;
 p23.y = (p2->y+p3->y)/2.0;
 p23.z = (p2->z+p3->z)/2.0;
 den = (p23.x*p23.x)+(p23.y*p23.y)+(p23.z*p23.z); 
 den = sqrt(den);
 if (den != 0.0) {

 t = radius / den;
 p23.x *= t; 
 p23.y *= t; 
 p23.z *= t;

 }
 subdivide_tri(p1, &p12,&p13,a-1);
 subdivide_tri(&p12, p2, &p23,a-1);
 subdivide_tri(&p13,&p23, p3, a-1);
 subdivide_tri(&p12,&p23,&p13,a-1);

 } else {

 n1.x = p1->x; 
 n1.y = p1->y; 
 n1.z = p1->z; 
 norm_pt(&n1);
 n2.x = p2->x; 
 n2.y = p2->y; 
 n2.z = p2->z; 
 norm_pt(&n2);
 n3.x = p3->x; 
 n3.y = p3->y; 
 n3.z = p3->z; 
 norm_pt(&n3);

/* nothing special about this poly */

